SELECT kind, object_name, ordinal, detail FROM (SELECT 'column' AS kind, 't2' AS object_name, cid AS ordinal, name || ':' || type || ':' || "notnull" || ':' || pk AS detail FROM pragma_table_info('t2') UNION ALL SELECT 'index-column', 't2ab', seqno, name FROM pragma_index_info('t2ab') UNION ALL SELECT 'index-column', 't2ba', seqno, name FROM pragma_index_info('t2ba') UNION ALL SELECT 'index-meta', name, 0, CAST("unique" AS TEXT) || ':' || origin || ':' || partial FROM pragma_index_list('t2') WHERE name IN ('t2ab','t2ba')) ORDER BY kind, object_name, ordinal;